import itertools
import sys

# Edges in lex order
vertices = list(range(7))
edges = [(i,j) for i in vertices for j in vertices if i < j]
print(len(edges))  # should be 21
edge_to_idx = {e: idx for idx, e in enumerate(edges)}

# Fixed: c[3]=0, c[7]=0, c[12]=0, c[18]=0
fixed = {3:0, 7:0, 12:0, 18:0}
free_indices = [i for i in range(21) if i not in fixed]

# Function to get coloring list from free values
def get_coloring(free_vals):
    coloring = [0]*21
    for idx, val in zip(free_indices, free_vals):
        coloring[idx] = val
    for fidx, val in fixed.items():
        coloring[fidx] = val
    return coloring

# Function to check if edge is red (0) or blue(1)
def is_red(coloring, u, v):
    if u > v: u,v = v,u
    idx = edge_to_idx[(u,v)]
    return coloring[idx] == 0

def is_blue(coloring, u, v):
    return not is_red(coloring, u, v)

# Check no red K4
def has_red_k4(coloring):
    for comb in itertools.combinations(vertices, 4):
        all_red = True
        for a,b in itertools.combinations(comb,2):
            if not is_red(coloring, a,b):
                all_red = False
                break
        if all_red:
            return True
    return False

# Check no blue K3
def has_blue_k3(coloring):
    for comb in itertools.combinations(vertices, 3):
        all_blue = True
        for a,b in itertools.combinations(comb,2):
            if not is_blue(coloring, a,b):
                all_blue = False
                break
        if all_blue:
            return True
    return False

# Now brute force
found = False
solution = None
for free_vals in itertools.product([0,1], repeat=len(free_indices)):
    col = get_coloring(free_vals)
    if not has_red_k4(col) and not has_blue_k3(col):
        found = True
        solution = col
        break

print(found)
if found:
    print(solution)
else:
    print("UNSATISFIABLE")
